/**
 * @module config
 * @description Configuration types and defaults for SmAnnotate embedding.
 *
 * SmAnnotate supports multiple layout modes, mobile optimizations, and
 * customizable features. Pass a partial config to the constructor to
 * customize behavior:
 *
 * @example
 * ```typescript
 * import { SmAnnotate, SmAnnotateConfig } from '@lifeart/sm-annotate';
 *
 * const config: Partial<SmAnnotateConfig> = {
 *   layout: 'vertical',
 *   mobile: { gesturesEnabled: true },
 * };
 *
 * const tool = new SmAnnotate(videoElement, config);
 * ```
 */

import type { Theme } from "./ui/theme";
import type { Tool } from "./plugins";

/**
 * Layout modes for the annotation toolbar.
 *
 * - `horizontal`: Default layout with toolbar at top, player controls at bottom
 * - `vertical`: Tools in a vertical sidebar (configurable left/right)
 * - `minimal`: Compact floating toolbar that can be repositioned
 * - `bottom-dock`: All controls merged into a single bottom bar
 */
export type LayoutMode = 'horizontal' | 'vertical' | 'minimal' | 'bottom-dock';

/**
 * Position for toolbar placement
 */
export interface ToolbarPosition {
  x: number;
  y: number;
}

/**
 * Mobile-specific configuration options
 */
export interface MobileConfig {
  /** Enable collapsible toolbars on mobile */
  collapsibleToolbars: boolean;
  /** Enable pinch-to-zoom and pan gestures */
  gesturesEnabled: boolean;
  /** Auto-collapse toolbar when drawing starts */
  autoCollapse: boolean;
  /** Viewport width breakpoint for mobile mode (default: 960) */
  breakpoint: number;
}

/**
 * Toolbar configuration options
 */
export interface ToolbarConfig {
  /** Initial position for minimal/floating layout */
  position?: ToolbarPosition;
  /** Allow dragging the toolbar (minimal layout) */
  draggable?: boolean;
  /** Sidebar position for vertical layout */
  sidebarPosition?: 'left' | 'right';
  /** Default selected tool on init (null = no tool selected) */
  defaultTool?: Tool | null;
}

/**
 * Feature visibility flags
 */
export interface FeatureFlags {
  /** Show theme toggle button */
  showThemeToggle: boolean;
  /** Show fullscreen button */
  showFullscreen: boolean;
  /** Show progress bar overlay */
  showProgressBar: boolean;
  /** Show frame counter overlay */
  showFrameCounter: boolean;
}

/**
 * Ghost mode (onion skinning) configuration.
 * Shows annotations from adjacent frames as semi-transparent overlays
 * to help with animation continuity and review.
 */
export interface GhostConfig {
  /** Enable ghost mode on startup */
  enabled: boolean;
  /** Number of previous frames to show as ghosts (1-5) */
  framesBefore: number;
  /** Number of next frames to show as ghosts (1-5) */
  framesAfter: number;
  /** Base opacity for ghost frames (0.1-0.5), decreases with distance */
  opacity: number;
  /** Tint color for previous frames (CSS color string, or null for original) */
  tintBefore: string | null;
  /** Tint color for next frames (CSS color string, or null for original) */
  tintAfter: string | null;
}

/**
 * Main configuration interface for SmAnnotate
 */
export interface SmAnnotateConfig {
  /** Layout mode for toolbars */
  layout: LayoutMode;
  /** Mobile-specific settings */
  mobile: MobileConfig;
  /** Initial theme */
  theme: Theme;
  /** Toolbar positioning options */
  toolbar: ToolbarConfig;
  /** Feature visibility flags */
  features: FeatureFlags;
  /** Ghost mode (onion skinning) settings */
  ghost: GhostConfig;
}

/**
 * Default configuration values
 */
export const defaultConfig: SmAnnotateConfig = {
  layout: 'horizontal',
  mobile: {
    collapsibleToolbars: true,
    gesturesEnabled: true,
    autoCollapse: true,
    breakpoint: 960,
  },
  theme: 'dark',
  toolbar: {
    draggable: false,
    sidebarPosition: 'left',
    defaultTool: 'curve',
  },
  features: {
    showThemeToggle: true,
    showFullscreen: true,
    showProgressBar: true,
    showFrameCounter: true,
  },
  ghost: {
    enabled: false,
    framesBefore: 2,
    framesAfter: 1,
    opacity: 0.3,
    tintBefore: 'rgba(255, 0, 0, 0.3)',
    tintAfter: 'rgba(0, 128, 0, 0.3)',
  },
};

/**
 * Merge partial config with defaults
 */
export function mergeConfig(partial?: Partial<SmAnnotateConfig>): SmAnnotateConfig {
  if (!partial) {
    return { ...defaultConfig };
  }

  return {
    layout: partial.layout ?? defaultConfig.layout,
    theme: partial.theme ?? defaultConfig.theme,
    mobile: {
      ...defaultConfig.mobile,
      ...partial.mobile,
    },
    toolbar: {
      ...defaultConfig.toolbar,
      ...partial.toolbar,
    },
    features: {
      ...defaultConfig.features,
      ...partial.features,
    },
    ghost: {
      ...defaultConfig.ghost,
      ...partial.ghost,
    },
  };
}
